// Priority ordering: Deals first → Trends → Product Launch → Regulatory → Other
// Within each category: trending first, then by confidence_score
const PRIORITY = { 'Deals': 1, 'Trends': 2, 'Product Launch': 3, 'Regulatory': 4, 'Other': 5 };

const articles = Array.isArray(items[0].json) ? items[0].json : [items[0].json];

const sorted = [...articles].sort((a, b) => {
  const pa = PRIORITY[a.category] || 5;
  const pb = PRIORITY[b.category] || 5;
  if (pa !== pb) return pa - pb;
  if (a.trending_flag !== b.trending_flag) return b.trending_flag - a.trending_flag;
  return (b.confidence_score || 0) - (a.confidence_score || 0);
});

console.log(`Publishing ${sorted.length} articles`);
return sorted.map(a => ({ json: a }));

// Collect all article IDs for bulk publish update
const ids = items.map(i => i.json.id).filter(Boolean);
const articles = items.map(i => i.json);
const now = new Date().toISOString();

return [{ json: { ids, articles, published_at: now } }];

