const nlResp = items[0].json;
const publishData = $('Mark as Published').first().json;
const articles = publishData.articles || [];

const nlText = nlResp?.content?.[0]?.text || 'Newsletter generation failed.';
const today = new Date();
const dateStr = today.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

const stats = {
  total_articles: articles.length,
  deals: articles.filter(a => a.category === 'Deals').length,
  trends: articles.filter(a => a.category === 'Trends').length,
  trending: articles.filter(a => a.trending_flag).length,
};

const highlights = articles
  .filter(a => a.category === 'Deals' || a.trending_flag)
  .slice(0, 3)
  .map(a => ({
    headline: a.headline,
    summary: a.summary,
    companies: a.companies,
    deal_type: a.deal_type,
    url: a.original_url,
  }));

return [{
  json: {
    title: `FMCG Deal Intelligence — ${dateStr}`,
    date_range: dateStr,
    edition: 'Daily',
    content_text: nlText,
    article_ids: JSON.stringify(publishData.ids || []),
    highlights: JSON.stringify(highlights),
    stats: JSON.stringify(stats),
  }
}];
